<?php
declare(strict_types=1);
require __DIR__.'/install-lock.php';
lqi_guard_installer();
if(session_status()!==PHP_SESSION_ACTIVE){session_name('LQRINSTALL');session_start();}
const LQI_SCHEMA_VERSION='2026.07.10-production-foundation-v1';
require __DIR__.'/install-functions.php';

$defaults=['app_name'=>'Local Quest Rewards','app_public_url'=>'https://quest.example.com','base_url'=>'https://microgifter.com','mode'=>'test','allow_sandbox_shortcut'=>'','db_host'=>'127.0.0.1','db_name'=>'local_quest_rewards','db_user'=>'','api_key'=>'','default_program_id'=>'','default_template_id'=>'','webhook_secret'=>'','signed_code_secret'=>'','owner_username'=>'owner','owner_email'=>''];
$values=array_merge($defaults,$_POST);$message='';$error='';$backup=null;$checks=lqi_diagnostics();
try{
    lqi_check_token();
    if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'&&lqi_post('action')==='install'){
        $dbHost=lqi_post('db_host');$dbName=lqi_post('db_name');$dbUser=lqi_post('db_user');$dbPassword=lqi_secret('db_secret');
        $ownerPassword=lqi_secret('owner_secret');$ownerConfirm=lqi_secret('owner_secret_confirm');$appUrl=rtrim(lqi_post('app_public_url'),'/');$baseUrl=rtrim(lqi_post('base_url'),'/');$mode=lqi_post('mode')==='live'?'live':'test';
        if(!preg_match('/^[A-Za-z0-9_]+$/',$dbName))throw new RuntimeException('Database name may contain only letters, numbers, and underscores.');
        if($dbHost===''||$dbUser==='')throw new RuntimeException('Database host and user are required.');
        if(!filter_var($appUrl,FILTER_VALIDATE_URL)||!filter_var($baseUrl,FILTER_VALIDATE_URL))throw new RuntimeException('Enter valid application and Microgifter URLs.');
        if($mode==='live'&&!str_starts_with($appUrl,'https://'))throw new RuntimeException('Live mode requires an HTTPS application URL.');
        if(!filter_var(lqi_post('owner_email'),FILTER_VALIDATE_EMAIL))throw new RuntimeException('Enter a valid owner email address.');
        if(!preg_match('/^[a-zA-Z0-9_.-]{3,80}$/',lqi_post('owner_username')))throw new RuntimeException('Owner username must be 3–80 safe characters.');
        if(strlen($ownerPassword)<12||$ownerPassword!==$ownerConfirm)throw new RuntimeException('Owner password must be at least 12 characters and match.');
        foreach(['api_key','default_program_id','default_template_id','webhook_secret'] as $key)if(lqi_secret($key)==='')throw new RuntimeException($key.' is required.');
        try{$root=lqi_pdo($dbHost,'',$dbUser,$dbPassword,false);$root->exec('CREATE DATABASE IF NOT EXISTS `'.str_replace('`','``',$dbName).'` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');}catch(Throwable){}
        $pdo=lqi_pdo($dbHost,$dbName,$dbUser,$dbPassword,true);foreach(lqi_schema_paths() as $schema)lqi_run_sql_file($pdo,$schema);
        $missing=lqi_missing_tables($pdo);if($missing!==[])throw new RuntimeException('Required tables are missing: '.implode(', ',$missing));
        $ownerHash=password_hash($ownerPassword,PASSWORD_DEFAULT);lqi_seed_owner($pdo,lqi_post('owner_username'),lqi_post('owner_email'),$ownerHash);
        $api=lqi_api_test($baseUrl,lqi_secret('api_key'));if(!$api['ok'])throw new RuntimeException($api['detail'].' Confirm the API key and base URL.');
        $backup=lqi_write_config(['app_name'=>lqi_post('app_name'),'app_public_url'=>$appUrl,'base_url'=>$baseUrl,'api_key'=>lqi_secret('api_key'),'default_program_id'=>lqi_post('default_program_id'),'default_template_id'=>lqi_post('default_template_id'),'webhook_secret'=>lqi_secret('webhook_secret'),'mode'=>$mode,'allow_sandbox_shortcut'=>$mode==='test'&&lqi_bool('allow_sandbox_shortcut'),'signed_code_secret'=>lqi_secret('signed_code_secret')?:bin2hex(random_bytes(32)),'owner_username'=>lqi_post('owner_username'),'owner_email'=>lqi_post('owner_email'),'owner_hash'=>$ownerHash,'db_host'=>$dbHost,'db_name'=>$dbName,'db_user'=>$dbUser,'db_secret'=>$dbPassword]);
        lqi_write_lock();@unlink(lqi_unlock_path());$_SESSION['lqi_csrf']=bin2hex(random_bytes(32));$message='Installation complete. Database, configuration, owner, API connectivity, and installer lock were verified.';$checks=lqi_diagnostics(['host'=>$dbHost,'name'=>$dbName,'user'=>$dbUser,'password'=>$dbPassword]);
    }
}catch(Throwable $e){$error=$e->getMessage();}
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Install Local Quest Rewards</title><style>:root{--bg:#f2f6f2;--surface:#fff;--ink:#15201a;--muted:#66736b;--line:#dbe5de;--green:#145f43;--red:#b42318;--shadow:0 24px 70px rgba(25,54,40,.11)}*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 12% 0,rgba(225,245,111,.32),transparent 25%),var(--bg);color:var(--ink);font-family:Inter,system-ui,-apple-system,"Segoe UI",sans-serif}.wrap{width:min(1180px,94%);margin:0 auto;padding:42px 0 80px}.hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:30px;align-items:end;margin-bottom:24px}.mark{width:48px;height:48px;border-radius:15px;background:var(--green);color:#fff;display:grid;place-items:center;font-weight:950}.eyebrow{color:var(--green);font-size:11px;font-weight:950;letter-spacing:.1em;text-transform:uppercase}h1{font-size:clamp(42px,6vw,72px);line-height:.93;letter-spacing:-.075em;margin:18px 0 12px}h2{margin:0 0 8px}h3{margin:0}p{color:var(--muted);line-height:1.65}.badge{padding:8px 11px;border-radius:999px;background:#fff;border:1px solid var(--line);font-size:11px;font-weight:900}.card{background:#fff;border:1px solid var(--line);border-radius:22px;padding:22px;margin:14px 0;box-shadow:var(--shadow)}.checks,.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.check{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:12px;padding:13px;border:1px solid var(--line);border-radius:13px}.check small{display:block;color:var(--muted);margin-top:4px}.status{font-size:10px;font-weight:950;padding:7px 9px;border-radius:999px;height:max-content}.ok{background:#e8f7ed;color:#12643a}.bad{background:#fff0ef;color:var(--red)}.group{padding:18px;border:1px solid var(--line);border-radius:16px;background:#fbfcfa}label{display:block;margin-top:12px;color:#34463d;font-size:12px;font-weight:900}input,select{width:100%;min-height:45px;margin-top:6px;border-radius:12px;border:1px solid var(--line);background:#fff;color:var(--ink);padding:0 12px;font:inherit}.checkline{display:flex;gap:9px;align-items:flex-start;color:var(--muted)}.checkline input{width:auto;min-height:0}.notice{padding:14px 16px;border-radius:14px;background:#eaf7ee;color:#155b37;border:1px solid #bfe3ca}.error{background:#fff0ef;color:var(--red);border-color:#f0c4c0}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}.btn,button{display:inline-flex;align-items:center;justify-content:center;min-height:46px;padding:0 17px;border-radius:13px;background:var(--green);color:#fff;border:0;font-weight:950;text-decoration:none;cursor:pointer}.secondary{background:#fff;color:var(--ink);border:1px solid var(--line)}code{background:#eef3ef;padding:3px 6px;border-radius:6px}@media(max-width:850px){.hero,.grid,.checks{grid-template-columns:1fr}}</style></head><body><main class="wrap"><section class="hero"><div><span class="mark">LQ</span><span class="eyebrow">Production setup</span><h1>Install Local Quest Rewards.</h1><p>Configure SQL storage, Microgifter API access, security secrets, and the first owner. The installer verifies the schema and locks itself after success.</p></div><span class="badge">Schema <?= lqi_h(LQI_SCHEMA_VERSION) ?></span></section><?php if($message):?><div class="notice"><strong><?=lqi_h($message)?></strong><?php if($backup):?><br><small>Previous config backup: <code><?=lqi_h(basename($backup))?></code></small><?php endif;?><div class="actions"><a class="btn" href="cover.php">Open public site</a><a class="btn secondary" href="admin-credentials.php">Admin sign in</a><a class="btn secondary" href="runtime-diagnostics.php">Diagnostics</a></div></div><?php endif;?><?php if($error):?><div class="notice error"><strong>Installation stopped.</strong><br><?=lqi_h($error)?></div><?php endif;?><section class="card"><h2>Server readiness</h2><div class="checks"><?php foreach($checks as $check):?><div class="check"><div><strong><?=lqi_h($check['name'])?></strong><small><?=lqi_h($check['detail'])?></small></div><span class="status <?=$check['ok']?'ok':'bad'?>"><?=$check['ok']?'PASS':'OPEN'?></span></div><?php endforeach;?></div></section><?php if(!$message):?><form method="post" class="card" autocomplete="off"><input type="hidden" name="_lqi_csrf" value="<?=lqi_h(lqi_token())?>"><input type="hidden" name="action" value="install"><div class="grid"><section class="group"><h3>Application</h3><label>Name<input name="app_name" value="<?=lqi_h((string)$values['app_name'])?>" required></label><label>Public URL<input type="url" name="app_public_url" value="<?=lqi_h((string)$values['app_public_url'])?>" required></label><label>Mode<select name="mode"><option value="test" <?=($values['mode']??'')==='test'?'selected':''?>>Test</option><option value="live" <?=($values['mode']??'')==='live'?'selected':''?>>Live</option></select></label><label class="checkline"><input type="checkbox" name="allow_sandbox_shortcut" value="1" <?=!empty($values['allow_sandbox_shortcut'])?'checked':''?>> Allow sandbox linking in test mode</label></section><section class="group"><h3>Database</h3><label>Host<input name="db_host" value="<?=lqi_h((string)$values['db_host'])?>" required></label><label>Name<input name="db_name" value="<?=lqi_h((string)$values['db_name'])?>" required></label><label>User<input name="db_user" value="<?=lqi_h((string)$values['db_user'])?>" required></label><label>Password<input type="password" name="db_secret"></label></section></div><div class="grid" style="margin-top:18px"><section class="group"><h3>Microgifter</h3><label>Base URL<input type="url" name="base_url" value="<?=lqi_h((string)$values['base_url'])?>" required></label><label>Developer API key<input type="password" name="api_key" required></label><label>Distribution Program ID<input name="default_program_id" value="<?=lqi_h((string)$values['default_program_id'])?>" required></label><label>Reward template ID<input name="default_template_id" value="<?=lqi_h((string)$values['default_template_id'])?>" required></label><label>Webhook signing value<input type="password" name="webhook_secret" required></label><label>Signed-code secret (optional)<input type="password" name="signed_code_secret"></label></section><section class="group"><h3>First owner</h3><label>Username<input name="owner_username" value="<?=lqi_h((string)$values['owner_username'])?>" required></label><label>Email<input type="email" name="owner_email" value="<?=lqi_h((string)$values['owner_email'])?>" required></label><label>Password<input type="password" name="owner_secret" minlength="12" required></label><label>Confirm password<input type="password" name="owner_secret_confirm" minlength="12" required></label><p>The owner controls administrators, quests, diagnostics, webhooks, and deployment settings.</p></section></div><div class="actions"><button type="submit">Review and install</button><a class="btn secondary" href="README.md">Deployment guide</a></div></form><script src="assets/form-review.js"></script><?php endif;?></main></body></html>
